import math
from sympy.ntheory import factorint
import sympy

# Top-level setup: named object bindings
# Expected witness format:
# A dictionary {'n': n, 'm': m, 'q': q} or a tuple (n, m, q)
# representing:
# R = Z/nZ
# S = Z/mZ
# f: R -> S given by the natural projection f(x) = x mod m
# Q = ideal generated by q in S
x, y, z = sympy.symbols('x y z')

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, dict):
            n = int(witness['n'])
            m = int(witness['m'])
            q_raw = witness['q']
        elif isinstance(witness, (list, tuple)) and len(witness) == 3:
            n = int(witness[0])
            m = int(witness[1])
            q_raw = witness[2]
        else:
            n = int(witness.n)
            m = int(witness.m)
            q_raw = witness.q
            
        if isinstance(q_raw, (list, tuple)):
            q = int(q_raw[0])
            for val in q_raw[1:]:
                q = math.gcd(q, int(val))
        else:
            q = int(q_raw)
            
        # Prevent DOS from excessively large integers
        if abs(n) > 10**6 or abs(m) > 10**6 or abs(q) > 10**6:
            return [False, False, False, False]
    except Exception:
        return [False, False, False, False]

    # H_1: R and S are commutative rings with identity
    # Z/nZ and Z/mZ are commutative rings with identity for n, m >= 2.
    try:
        h1 = (n >= 2) and (m >= 2)
    except Exception:
        h1 = False

    # H_2: f is a ring homomorphism from R to S
    # f(x) = x mod m is a well-defined ring homomorphism iff m divides n.
    try:
        h2 = (n % m == 0)
    except Exception:
        h2 = False

    # H_3: f maps the multiplicative identity of R to the multiplicative identity of S
    # 1_R = 1, 1_S = 1. f(1) = 1 mod m = 1 (since m >= 2).
    # This holds whenever f is well-defined (m divides n).
    try:
        h3 = (n % m == 0)
    except Exception:
        h3 = False

    # ¬Q: The preimage of Q under f is not a primary ideal of R
    # Q is the ideal generated by q in Z/mZ.
    # The preimage of Q in Z/nZ is the ideal generated by gcd(q, m).
    # An ideal generated by k in Z/nZ is primary iff k is a prime power.
    try:
        k = math.gcd(q, m)
        if k < 2:
            # k=1 means the ideal is the whole ring, which is not proper, hence not primary.
            neg_q = True
        else:
            factors = factorint(k)
            # It is a prime power if there is exactly one prime factor.
            is_prime_power = (len(factors) == 1)
            neg_q = not is_prime_power
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]

CONDITION_LABELS = [
    "H_1: R and S are commutative rings with identity",
    "H_2: f is a ring homomorphism from R to S",
    "H_3: f maps the multiplicative identity of R to the multiplicative identity of S",
    "¬Q: The preimage of Q under f is not a primary ideal of R"
]

N_HYP = 3
NEG_Q_INDEX = 3